 JSONObject schedule()throws Exception{JSONObject root=new JSONObject().put("season",new JSONObject().put("year",2026));JSONObject team=new JSONObject().put("id","8").put("displayName","Detroit Lions").put("abbreviation","DET").put("logo","").put("recordSummary","2-2").put("standingSummary","NFC North");root.put("team",team);JSONArray games=new JSONArray();for(int i:new int[]{1,3}){JSONObject cp=new JSONObject().put("team",team).put("homeAway","home").put("score",new JSONObject().put("displayValue","31"));JSONObject opp=new JSONObject().put("team",new JSONObject().put("id","18").put("displayName","Saints").put("abbreviation","NO")).put("homeAway","away").put("score",new JSONObject().put("displayValue","30"));JSONObject c=new JSONObject().put("status",new JSONObject().put("type",new JSONObject().put("state","post").put("completed",true))).put("competitors",new JSONArray().put(cp).put(opp)).put("broadcasts",new JSONArray().put(new JSONObject().put("media",new JSONObject().put("shortName","FOX"))));games.put(new JSONObject().put("id","game"+i).put("date",i==1?"2026-09-13T17:00Z":"2026-09-27T17:00Z").put("week",new JSONObject().put("number",i)).put("competitions",new JSONArray().put(c)));}return root.put("events",games);}
