 @Test public void teamWeeksFilterGamesAndRespectSpoilersInsideProShell()throws Exception{pro();Object team=SportsHubTest.team("8","nfl|8","Detroit Lions","DET","");put(team,"leagueKey","nfl");((Map)get(a,"mCobraProTeamDirectory")).put("nfl",new ArrayList(Arrays.asList(team)));Object season=call(a,"cobraParseTeamSeason",call(a,"cobraSportsSpec","nfl"),team,schedule(),System.currentTimeMillis());((Map)get(a,"mCobraProTeamSeasons")).put("nfl|8",season);Object video=get(a,"mCobraPreviewTexture");call(a,"cobraProFilter",4);call(a,"cobraProSportsTab",4);call(a,"cobraProOpenTeam",team);put(a,"mCobraProTeamWeek",1);call(a,"cobraRenderGuideBrowser");f.measure(a,412,915);View browser=(View)get(a,"mCobraGuideBrowser");assertNotNull(browser.findViewWithTag("pro_team_game_game1"));assertNull(browser.findViewWithTag("pro_team_game_game3"));assertSame(video,get(a,"mCobraPreviewTexture"));f.frames(30);f.measure(a,412,915);f.image(a,"pro-team-week1-317");prefs.protection(true);call(a,"cobraRenderGuideBrowser");assertFalse(text((View)get(a,"mCobraGuideBrowser")).contains("31"));assertFalse(text((View)get(a,"mCobraGuideBrowser")).contains("2-2"));prefs.protection(false);put(a,"mCobraProTeamWeek",2);call(a,"cobraRenderGuideBrowser");assertTrue(text((View)get(a,"mCobraGuideBrowser")).contains("No games scheduled this week"));f.measure(a,412,915);f.frames(30);f.measure(a,412,915);f.image(a,"pro-team-details-317");}
 @Test public void realLeagueScheduleShapesMergeSeasonAndKeepCalendarWeeks()throws Exception{
  String raw;try(InputStream in=getClass().getResourceAsStream("/schedule-fixtures.json")){assertNotNull(in);raw=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}JSONObject fixtures=new JSONObject(raw);
  for(String key:new String[]{"nfl","nba","nhl","mlb","epl"}){JSONObject input=fixtures.getJSONObject(key),regular=input.getJSONObject("regular"),current=input.getJSONObject("current");Object spec=call(a,"cobraSportsSpec",key),team=call(a,"cobraDirectoryTeam",spec,regular.getJSONObject("team"));JSONObject merged=(JSONObject)call(a,"cobraMergeTeamSchedules",spec,regular,key.equals("epl")?null:current,key.equals("epl")?current:null);Object season=call(a,"cobraParseTeamSeason",spec,team,merged,System.currentTimeMillis());List<?> weeks=(List<?>)get(season,"weeks");assertTrue(key+" has full season bounds",weeks.size()>=18);int games=0;Set<String> ids=new HashSet<>();for(Object week:weeks)for(Object game:(List<?>)get(week,"games")){assertTrue(key+" duplicate",ids.add((String)get(game,"id")));games++;}assertTrue(key+" preserves both schedule phases",games>=4);if(key.equals("nfl"))assertEquals(18,weeks.size());}
 }
