 @Test public void officialFootballCalendarKeepsMondayGamesInTheirPublishedWeek()throws Exception{JSONObject raw=schedule();raw.getJSONArray("events").getJSONObject(0).put("date","2026-09-14T23:15Z");raw.put("weekCalendar",new JSONArray().put(new JSONObject().put("number",1).put("startDate","2026-09-06T07:00Z").put("endDate","2026-09-16T06:59Z").put("detail","Sep 6-15")));Object season=call(a,"cobraParseTeamSeason",call(a,"cobraSportsSpec","nfl"),SportsHubTest.team("8","nfl|8","Lions","DET",""),raw,0L);Object week=((List)get(season,"weeks")).get(0);assertEquals("Sep 6 – 15",call(a,"cobraTeamRange",week));Object game=((List)get(week,"games")).get(0);assertTrue((Long)get(game,"startMs")>=(Long)get(week,"from"));assertTrue((Long)get(game,"startMs")<(Long)get(week,"to"));assertEquals(1,get(week,"number"));}

